<?php
try{
 if($_SERVER['REQUEST_METHOD']==='POST'){
  verify_csrf();adjustment_access();$lock=inventory_write_lock();
  if(in_array($action,['final_create','create','manual_create'],true)){$id=($action==='manual_create'||($_POST['entry_method']??'')==='Manual')?manual_adjustment_create($_POST):final_count_create($_POST);flash('Final-count attempt created. Enter one final count; no mandatory recount. No stock changed.');}
  elseif($action==='final_upload'){$b=final_count_open($id,true);final_count_owner($b);if($b['status']!=='Exported')throw new Exception('This attempt already has evidence. Close it before a linked replacement.');$file=$_FILES['file']??[];validate_upload_file($file,['xlsx']);$hash=hash_file('sha256',$file['tmp_name']);try{$rows=XlsxReader::rows($file['tmp_name']);}catch(Throwable $readError){$rows=[];}$stored=store_upload($file,'count_evidence','FINAL');$errors=final_count_upload($id,$rows,$file['name'],$hash,$stored,$_POST);flash($errors?'Final count has validation errors. Cancel this attempt with a reason before a new linked attempt.':'Final count validated. Review system quantity, counted quantity and variance before submission. No stock changed.',$errors?'danger':'info');}
  elseif($action==='final_manual'){$errors=final_count_manual_save($id,$_POST);flash($errors?'Final count has validation errors. Use Cancel / Back to start a linked corrected attempt.':'Manual final count validated. Review and submit; no mandatory recount.',$errors?'danger':'info');}
  elseif($action==='final_submit'){final_count_submit($id,$_POST['revision']??0,!empty($_POST['review_ack']));flash('Final count submitted and locked for review. No stock changed.');}
  elseif($action==='final_review'){final_count_review($id,$_POST['revision']??0,!empty($_POST['review_ack']));flash('Reviewed. A different Admin must approve and post.');}
  elseif($action==='final_post'){final_count_post($id,$_POST['digest']??'',!empty($_POST['review_ack']));flash('Final count adjustment and platform redistribution posted once. Later movements were retained.');}
  elseif(in_array($action,['final_cancel','final_return'],true)){final_count_close($id,$_POST['reason']??'',$action==='final_return');flash('Attempt closed. Original evidence remains in history; create a linked corrected attempt if needed. No adjustment posted.');}
  else throw new Exception('Use the Final Count actions on this record.');
  inventory_write_unlock($lock);$lock=null;header('Location: index.php?page=inventory_count&id='.$id);exit;
 }
 $b=count_batch($id);if(!final_count_is($b))throw new Exception('Select a final-count record.');$scope=final_count_meta($b)['count_scope'];
 if(isset($_GET['evidence'])){$q=db()->prepare('SELECT * FROM count_upload_evidence WHERE id=? AND batch_id=?');$q->execute([(int)$_GET['evidence'],$id]);$v=$q->fetch();$base=realpath(__DIR__.'/uploads/count_evidence');$path=$v?realpath(__DIR__.'/'.$v['stored_path']):false;if(!$path||!$base||!str_starts_with(str_replace('\\','/',$path),str_replace('\\','/',$base).'/')||!hash_equals($v['file_hash'],hash_file('sha256',$path)))throw new Exception('Original evidence is unavailable or changed.');header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="final_count_evidence_'.$v['id'].'.xlsx"');readfile($path);exit;}
 if(isset($_GET['download'])){$path=tempnam(sys_get_temp_dir(),'final-count-');try{final_count_export($id,$path);header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="'.$b['batch_ref'].'_Final_Count.xlsx"');readfile($path);}finally{if(is_file($path))unlink($path);}exit;}
 if(isset($_GET['print'])){$rows=[];foreach(count_lines($id) as $l)$rows[]=array_merge([$l['master_sku']],array_fill(0,$scope==='Sellable'?1:4,''));report_print_document('Final Inventory Count Sheet',final_count_headers($scope),$rows,['Attempt'=>$b['batch_ref'],'Count Scope'=>$scope,'Count Cutoff'=>$b['cutoff_at'],'Counted By'=>'________________','Instructions'=>'Blank means not counted; 0 means counted zero. System quantity is hidden.']);exit;}
 if(isset($_GET['results'])){$rows=[];foreach(count_lines($id) as $l){if($l['actual_count']===null)continue;$snap=json_decode($l['snapshot_conditions'],true);$count=json_decode($l['final_conditions'],true);$system=$scope==='Sellable'?$snap['good']:array_sum($snap);$actual=$scope==='Sellable'?$count['good']:array_sum($count);$rows[]=[$l['master_sku'],$l['product_name'],$scope,$system,$actual,$actual-$system];}$heads=['Master SKU','Product','Count Scope','System Quantity at Cutoff','Final Count','Variance'];$meta=['Attempt'=>$b['batch_ref'],'Count Cutoff'=>$b['cutoff_at'],'Status'=>$b['status'],'Reason'=>$b['reason'],'Supporting Reference'=>$b['support_reference'],'Reviewer'=>$b['reviewed_name'],'Approver'=>$b['approved_name']];if(($_GET['format']??'')==='print'){report_print_document('Final Count Validation & Adjustment',$heads,$rows,$meta);exit;}$path=tempnam(sys_get_temp_dir(),'final-result-');try{report_write_xlsx($path,'Final Count Validation & Adjustment',$heads,$rows,$meta);header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="'.$b['batch_ref'].'_Results.xlsx"');readfile($path);}finally{if(is_file($path))unlink($path);}exit;}
 header('Location: index.php?page=inventory_count&id='.$id);exit;
}catch(Throwable $ex){if(db()->inTransaction())db()->rollBack();if($id&&can_action('upload_inventory_count'))try{adjustment_event($id,'Rejected action',['action'=>$action,'error'=>safe_error_message($ex)]);}catch(Throwable $ignored){}inventory_write_unlock($lock);flash(safe_error_message($ex),'danger');header('Location: index.php?page=inventory_count'.($id?'&id='.$id:''));exit;}
